import sys

def main():
    import sys
    n = int(sys.stdin.read().strip())

    # Initial placement of knights
    knights = []
    for i in range(n):
        knights.append((i, 0))

    # Function to count attacks on each cell
    def count_attacks(knights):
        from collections import defaultdict
        attacks = defaultdict(int)
        for x, y in knights:
            for dx, dy in [(2, 1), (1, 2), (-1, 2), (-2, 1), (-2, -1), (-1, -2), (1, -2), (2, -1)]:
                attacks[(x + dx, y + dy)] += 1
        return attacks

    # Process to add new knights
    while True:
        attacks = count_attacks(knights)
        new_knights = []
        for (x, y), count in attacks.items():
            if count >= 4 and (x, y) not in knights:
                new_knights.append((x, y))
        if not new_knights:
            break
        knights.extend(new_knights)

    # Output the final placement of knights
    for x, y in knights:
        print(x, y)

if __name__ == "__main__":
    main()
